  'insights.description':
    'असामान्य गतिविधि और बचत के सुझाव, जो तय नियमों से आपके अपने इतिहास की तुलना करके मिलते हैं। जब तक आप ख़ुद न बदलें, आपके रिकॉर्ड में कुछ नहीं बदलता।',
  'insights.howItWorks.title': 'सुझाव कैसे काम करते हैं',
  'insights.howItWorks.body':
    'Montra दिन में एक बार तय नियमों से आपके अपने इतिहास की जाँच करता है, जैसे “किसी श्रेणी में आपकी सामान्य राशि से कम से कम 3 गुना खर्च”। हर सुझाव में वे आँकड़े और नियम दिखते हैं जिनका इस्तेमाल हुआ। नियम तब तक इंतज़ार करते हैं जब तक तुलना के लिए काफ़ी इतिहास न हो, इसलिए सुझाव आने में समय लग सकता है। आपके लिए कुछ भी अपने आप नहीं किया जाता, और “असामान्य” का मतलब गलत नहीं है।',
